try {
  // Fecha y hora
  const now = new Date();
  const fecha = now.toLocaleDateString('es-EC');
  const hora = now.toLocaleTimeString('es-EC');

  // Seguridad en estructura de datos
  const reservas = $input.item.json?.data?.reservas ?? [];
  const totalReservas = reservas.length;

  // Construcción del asunto
  const subject = `📊 Reporte Diario UNIFIT – ${fecha}`;

  // Construcción del mensaje
  const message = `
Estimado equipo UNIFIT,

Este correo corresponde al **reporte diario automático de reservas**, generado por el sistema de monitoreo institucional.

📌 **Resumen ejecutivo**
Durante la fecha ${fecha}, el sistema registró un total de **${totalReservas} reservas** procesadas correctamente.

📈 **Detalle del reporte**
- Total de reservas registradas: ${totalReservas}
- Estado del procesamiento: COMPLETADO
- Fuente de datos: Sistema UNIFIT
- Fecha del reporte: ${fecha}
- Hora de generación: ${hora}

🧠 **Interpretación**
${
  totalReservas === 0
    ? 'No se registraron reservas en el período evaluado. Se recomienda verificar la disponibilidad de servicios o la actividad de usuarios.'
    : 'El volumen de reservas indica una operación normal del sistema.'
}

🛠 **Acciones recomendadas**
- Validar que las reservas se reflejen correctamente en los módulos administrativos.
- Revisar métricas históricas para análisis de demanda.
- No se requiere intervención técnica si los valores coinciden con lo esperado.

ℹ️ **Nota**
Este mensaje fue generado automáticamente por la plataforma UNIFIT mediante n8n.
Por favor, no responder a este correo.

—
Sistema de Reportes Automáticos  
Plataforma UNIFIT
  `.trim();

  // Log interno (simulación)
  console.log('--- MOCK EMAIL ---');
  console.log('Subject:', subject);
  console.log('Message:', message);
  console.log('------------------');

  // Retorno para nodo Gmail
  return {
    sent: true,
    subject,
    message,
    totalReservas,
    timestamp: now.toISOString()
  };

} catch (error) {
  return {
    sent: false,
    subject: '❌ Error en Reporte Diario UNIFIT',
    message: `
Se produjo un error durante la generación del reporte diario de reservas.

Detalle del error:
${error.message}

Fecha y hora:
${new Date().toISOString()}

Sistema UNIFIT
    `.trim()
  };
}

try {
  // Obtener resultados de los nodos previos
  const rest = $('Check REST API').first().json;
  const graphql = $('Check GraphQL').first().json;
  const ai = $('Check AI Service').first().json;

  const services = [
    { name: 'REST API', status: rest.status || 'error', detail: rest.detail || '' },
    { name: 'GraphQL', status: graphql.status || 'error', detail: graphql.detail || '' },
    { name: 'AI Service', status: ai.status || 'error', detail: ai.detail || '' }
  ];

  const failed = services.filter(s => s.status !== 'ok');
  const timestamp = new Date().toISOString();

  // 🟢 Caso: todos los servicios operativos
  if (failed.length === 0) {
    return {
      alert: false,
      subject: '✅ Health Check OK – Todos los servicios operativos',
      message: `
Hola equipo,

Este es un informe automático del sistema de monitoreo.

✅ Todos los servicios evaluados se encuentran funcionando correctamente al momento de la verificación.

Resumen del estado:
- REST API: OK
- GraphQL: OK
- AI Service: OK

No se requiere ninguna acción en este momento.

Fecha y hora del chequeo:
${timestamp}

Saludos,
Sistema de Monitoreo Automático
      `.trim(),
      timestamp
    };
  }

  // 🔴 Caso: uno o más servicios caídos
  const failedDetails = failed.map(s => {
    return `- ${s.name}
  Estado: ${s.status.toUpperCase()}
  Detalle: ${s.detail || 'No se proporcionó información adicional.'}`;
  }).join('\n\n');

  return {
    alert: true,
    subject: '🚨 ALERTA CRÍTICA – Fallo en servicios del sistema',
    message: `
⚠️ ALERTA AUTOMÁTICA DEL SISTEMA ⚠️

Se ha detectado un fallo en uno o más servicios críticos durante el último health check.

Servicios afectados:
${failedDetails}

Impacto potencial:
- Interrupción parcial o total de funcionalidades del sistema
- Posibles errores para usuarios finales
- Degradación del rendimiento general

Acciones recomendadas:
1. Verificar el estado del servicio afectado.
2. Revisar logs del servidor correspondiente.
3. Validar conectividad de red y certificados.
4. Reiniciar el servicio si aplica.
5. Escalar al equipo responsable si el problema persiste.

Fecha y hora de detección:
${timestamp}

Este mensaje fue generado automáticamente por n8n.
No responder a este correo.

—  
Sistema de Monitoreo y Alertas
      `.trim(),
      timestamp
    };

} catch (e) {
  return {
    alert: true,
    subject: '❌ ERROR EN HEALTH CHECK – Ejecución fallida',
    message: `
Se produjo un error durante la ejecución del health check automático.

Detalle del error:
${e.message}

Este fallo impide confirmar el estado real de los servicios y debe ser revisado con prioridad.

Fecha y hora:
${new Date().toISOString()}

Sistema de Monitoreo
    `.trim()
  };
}
